changeSet.sql:
ALTER TABLE document.payment_transactions ADD COLUMN IF NOT EXISTS buyer_in TEXT;
ALTER TABLE document.payment_transactions ADD COLUMN IF NOT EXISTS seller_in TEXT;

UPDATE document.payment_transactions pt
   SET buyer_in = c.buyer_in,
       seller_in = c.seller_in
  FROM document.contracts c
 WHERE c.id = pt.document_id;

ALTER TABLE document.payment_transactions DROP COLUMN IF EXISTS buyer_id;
ALTER TABLE document.payment_transactions DROP COLUMN IF EXISTS seller_id;
